def solution(input_str):
    l, r = map(int, input_str.strip().split())

    def gen_periodic_strings(limit):
        limit_len = len(bin(limit))
        all_periodic = set()

        def is_periodic(target):
            s = bin(target)[2:]
            n = len(s)
            for k in range(1, n):
                if n % k == 0:
                    pattern = s[:k]
                    if s == pattern * (n // k):
                        return True
            return False

        candidates = []
        for base in range(1, limit_len):
            res = {int('{}{}'.format(1, '0' * (base - 1)), 2)}
            for length in range(2, base + 1):
                # Generate string candidates of this length
                sub_candidates = []
                for nk in range(1, length):
                    if length % nk == 0:
                        pattern_length = nk
                        # Base pattern must start with '1'
                        subs = set()
                        def dfs(p):
                            if len(p) == pattern_length:
                                subs.add(p)
                                return
                            if len(p) == 0 or (len(p) == pattern_length and p[0] == '0'):
                                pass
                            for c in ['0', '1']:
                                if len(p) < pattern_length or (len(p) == 0 and c == '1'):
                                    new_p = p + c
                                    dfs(new_p)
                        dfs('')
                        for pat in subs:
                            cnt = 1
                            while cnt * pattern_length <= length:
                                num_s = pat * cnt
                                val = int(num_s, 2)
                                if val <= limit:
                                    sub_candidates.append(val)
                        break
            res |= set(sub_candidates)

        all_periodic.update(res)
        return sorted(all_periodic)

    result = sum(1 for x in gen_periodic_strings(r) if l <= x <= r)
    return f"{result}\n"
