    best = None
    best_area = float('inf')

    for i in range(n):
        for j in range(i + 1, n):
            p1, p2 = hull[i], hull[j]

            # Find point farthest from line p1-p2
            max_dist = -1
            p3 = None
            for k in range(n):
                if k == i or k == j:
                    continue
                dist = abs(cross_product(p1, p2, hull[k]))
                if dist > max_dist:
                    max_dist = dist
                    p3 = hull[k]

            if p3:
                area = triangle_area(p1, p2, p3)
                if area < best_area:
                    best_area = area
                    best = (p1, p2, p3)

    if best:
