def solution(input_str):
    lines = input_str.strip().split('\n')

    # Parse input
    first = lines[0].split()
    n = int(first[0])
    y = int(first[1])
    m = int(first[2])

    # Build constraint graph (0-indexed internally)
    adj = [[] for _ in range(n)]

    idx = 1
    pairs = []
    for _ in range(m):
        line = lines[idx].split()
        idx += 1
        a, b = int(line[0]) - 1, int(line[1]) - 1
        pairs.append((a, b))
        adj[a].append(b)

    # Check for cycles using DFS
    visited = [0] * n  # 0 = unvisited, 1 = visiting, 2 = visited
    has_cycle = False

    def dfs(u):
        nonlocal has_cycle
        visited[u] = 1
        for v in adj[u]:
            if visited[v] == 1:
                has_cycle = True
                return
            if visited[v] == 0:
                dfs(v)
                if has_cycle:
                    return
        visited[u] = 2

    for i in range(n):
        if visited[i] == 0:
            dfs(i)
            if has_cycle:
                break

    if has_cycle:
        return "The times have changed"

    # Memoization for counting valid topological sorts
    memo = {}

    def count_ways(mask):
        """Count valid topological sorts for the subset of professors in mask."""
        if mask == 0:
            return 1

        if memo.get(mask) is not None:
            return memo[mask]

        # Count ways where a valid professor is LAST in the ordering
        # A professor can be last if all their prerequisites are in the subset
        total = 0

        # All profiles in the subset
        for last in range(n):
            if mask & (1 << last):  # last is in this subset
                # Check if all prerequisites of 'last' are in the remaining subset without 'last'
                prerequisites = 0

                # Build prereq mask for this professor
                for p in adj[last]:
                    prerequisites |= (1 << p)

                # All prerequisites must be in the subset without this professor
                if prerequisites & mask:
                    # All prerequisites are in the current subset
                    # But they must all be in the subset without 'last' to make 'last' last
                    remaining_prereqs = prerequisites & ((1 << n) - 1)  # mask out nonexistent bits
                    if prerequisites == (remaining_prereqs & mask):
                        # Valid - all prereqs are in the remaining subset
                        remaining_mask = mask ^ (1 << last)
                        total += count_ways(remaining_mask)

        memo[mask] = total
        return total

    total_counts = count_ways((1 << n) - 1)

    # Calculate offset from year 2001
    offset = y - 2001

    # If no valid arrangements or offset out of range
    if total_counts == 0:
        return "The times have changed"

    k = offset - 1  # 0-indexed

    if k < 0 or k >= total_counts:
        return "The times have changed"

    # Build the k-th lexicographically smallest arrangement
    arrangement = []
    mask = 0  # Currently placed professors

    for _ in range(n):
        # Try professors 0 to n-1 in order (lexicographically)
        for p in range(n):
            if not (mask & (1 << p)):  # p not yet placed
                # Check if p can be a valid next element (all prereqs placed)
                can_place = True
                for prereq in adj[p]:
                    if not (mask & (1 << prereq)):
                        can_place = False
                        break

