def solution(input_text: str):
    import sys
    lines = input_text.strip().split('\n')

    if not lines:
        return "SECOND\n"

    first_line = lines[0].split()
    n, m, k = int(first_line[0]), int(first_line[1]), int(first_line[2])

    # Parse cuts
    v_cuts = set()  # x-coordinates where vertical cuts exist
    h_cuts = set()  # y-coordinates where horizontal cuts exist

    for i in range(k):
        coords = list(map(int, lines[i + 1].split()))
        if coords[0] == coords[2]:  # Vertical cut
            v_cuts.add(coords[0])
        else:  # Horizontal cut
            h_cuts.add(coords[1])

    # Total possible cuts
    total_h = m - 1
    total_v = n - 1

    # Remaining (uncut) lines in each direction
    remaining_h = m - 1 - len(h_cuts)
    remaining_v = n - 1 - len(v_cuts)

    # The winning condition is based on XOR sum of (remaining_h, remaining_v)
    # Actually we need to find the Grundy values for each dimension

    def grundy(x):
        return x & 1

    g_h = grundy(remaining_h)
    g_v = grundy(remaining_v)

    xor_sum = g_h ^ g_v

    if xor_sum == 0:
        return "SECOND\n"
    else:
        # FIRST wins, find a winning move
        if remaining_h > 0:
            # Find a horizontal cut position
            for y in range(1, m):
                if y not in h_cuts:
                    return f"FIRST\n0 {y} {m} {y}\n"
        if remaining_v > 0:
            # Find a vertical cut position  
            for x in range(1, n):
                if x not in v_cuts:
                    return f"FIRST\n{x} 0 {x} {m}\n"

    return "SECOND\n"
