def solution(n):
    digits = list(n)
    digit_sum = sum(int(d) for d in digits)

    # If already divisible by 3, return original (0 erasures is optimal)
    if digit_sum % 3 == 0:
        return n

    # Categorize indices by digit remainder mod 3
    r0 = [i for i, d in enumerate(digits) if int(d) % 3 == 0]
    r1 = [i for i, d in enumerate(digits) if int(d) % 3 == 1]
    r2 = [i for i, d in enumerate(digits) if int(d) % 3 == 2]

    def remove_at_indices(indices_to_remove):
        remaining = [digits[i] for i in range(len(digits)) if i not in indices_to_remove]
        if not remaining:
            return None
        result = ''.join(remaining)
        # Check leading zero: only "0" is allowed as result with leading zero
        if len(result) > 1 and result[0] == '0':
            return None
        return result

    def is_divisible(s):
        if not s:
            return False
        return int(s) % 3 == 0

    # Try removing 1 digit first (minimal erasures)
    if digit_sum % 3 == 1:
        # Try removing one digit with remainder 1
        for idx in r1:
            result = remove_at_indices([idx])
            if result and is_divisible(result):
                return result
        # Try removing two digits with remainder 2
        for i in range(len(r2)):
            for j in range(i + 1, len(r2)):
                result = remove_at_indices([r2[i], r2[j]])
                if result and is_divisible(result):
                    return result
    # sum % 3 == 2 case
    else:
        # Try removing one digit with remainder 2
        for idx in r2:
            result = remove_at_indices([idx])
            if result and is_divisible(result):
                return result
        # Try removing two digits with remainder 1
        for i in range(len(r1)):
            for j in range(i + 1, len(r1)):
                result = remove_at_indices([r1[i], r1[j]])
                if result and is_divisible(result):
