        last_digit: the most recent digit added
        prev_digit: digit before last_digit (or 0 for single digit)
        going_up: True if prev_digit > last_digit went up, False if went down
        """
        wavy_numbers.append(current_num)

        num_str = str(current_num)
        num_len = len(num_str)

        if num_len >= 15:
            return

        if num_len < 14:
            # Try to add next digit
            if going_up:
                # Last transition was UP (prev > last), next must go DOWN
                for d in range(0, last_digit):
                    new_num = current_num * 10 + d
                    if new_num > 10**14:
                        break
                    dfs(new_num, d, last_digit, False)
            else:
                # Last transition was DOWN (last < prev), next must go UP
                for d in range(last_digit + 1, 10):
                    new_num = current_num * 10 + d
                    if new_num > 10**14:
                        break
                    dfs(new_num, d, last_digit, True)

    # Generate all single digit numbers (1-9), then build from them
    for first in range(1, 10):
        # After first digit, for DFS we say going_up=False to allow next digit 
        # to either go up (d > first) or down (d < first)
        # We track that the NEXT digit we add will determine the going_up status
        dfs(first, first, 0, False)

    # Remove duplicates and sort
    wavy_numbers = sorted(set(wavy_numbers))

    # Find k-th wavy number divisible by n
    count = 0
    for num in wavy_numbers:
        count += 1
        if count == k and num % n == 0:
            return f"{num}\n"
        if count == k:
            break

    return '-1\n'


# Test solution
