    test_cases = [
        ('100 1\n', '-1\n'),
        ('97461 457\n', '1805270103\n'),
        ('123 4\n', '1845\n'),
    ]

    for inp, expected in test_cases:
        result = solution(inp)
        print(f"Input: {inp}")
        print(f"Expected: {expected}")
        print(f"Got: {result}")
        print(f"Match: {result == expected}")
        print()
