import math

def is_point_in_triangle(px, py, x1, y1, x2, y2, x3, y3):
    """Check if point (px, py) is inside triangle using cross products."""
    def cross_product(ax, ay, bx, by, cx, cy):
        return (cx - ax) * (cy - ay) - (cx - ay) * (cy - ax)

    d1 = cross_product(x1, y1, x2, y2, px, py)
    d2 = cross_product(x2, y2, x3, y3, px, py)
    d3 = cross_product(x3, y3, x1, y1, px, py)

    return (d1 >= -1e-9 and d2 >= -1e-9 and d3 >= -1e-9)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    triangles = []

    for i in range(1, n + 1):
        coords = list(map(float, lines[i].split()))
        triangles.append(coords)

    perimeter = 0.0
    samples_per_edge = 100
    eps = 1e-9

    for i in range(n):
        x1, y1, x2, y2, x3, y3 = triangles[i]

        # Three edges of the triangle
        edges = [(x1, y1, x2, y2), (x2, y2, x3, y3), (x3, y3, x1, y1)]

        for (ex1, ey1, ex2, ey2) in edges:
            edge_length = math.hypot(ex2 - ex1, ey2 - ey1)
            if edge_length < eps:
                continue

            uncovered_count = 0

            # Sample along the edge
            for s in range(samples_per_edge):
                px = ex1 + (ex2 - ex1) * s / samples_per_edge
                py = ey1 + (ey2 - ey1) * s / samples_per_edge

                # Check if this interior point is covered by any other triangle
                is_covered = False
                for j in range(n):
                    if i == j:
                        continue
                    if is_point_in_triangle(px, py, *triangles[j]):
                        is_covered = True
                        break

                if not is_covered:
                    uncovered_count += 1

            # Add proportion of edge that's visible
            perimeter += (uncovered_count / samples_per_edge) * edge_length

    return str(perimeter)
