    if cp4 == 0 and on_segment(cx, cy, dx, dy, bx, by):
        return True

    return False

def reflect_point(px, py, ax, ay, bx, by):
    dx = bx - ax
    dy = by - ay

    if dx == 0 and dy == 0:
        return px, py

    nx = -dy
    ny = dx
    length = math.sqrt(nx * nx + ny * ny)

    nx /= length
    ny /= length

    vx = px - ax
    vy = py - ay
    proj = vx * nx + vy * ny

    rx = px - 2 * proj * nx
    ry = py - 2 * proj * ny

    return rx, ry

def find_intersection(px1, py1, px2, py2, ax, ay, bx, by):
    denom = (px2 - px1) * (by - ay) - (py2 - py1) * (bx - ax)
    if abs(denom) < 1e-9:
        return None, None

    t = ((px1 - ax) * (by - ay) - (py1 - ay) * (bx - ax)) / denom
    return px1 + t * (px2 - px1), py1 + t * (py2 - py1)

def point_on_same_side(px, py, qx, qy, ax, ay, bx, by):
    cp1 = cross_product(ax, ay, bx, by, px, py)
    cp2 = cross_product(ax, ay, bx, by, qx, qy)
    return cp1 * cp2 > 0

def segments_intersection(xv, yv, xp, yp, x1, y1, x2, y2):
    xint, yint = find_intersection(xv, yv, xp, yp, x1, y1, x2, y2)
