            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    dist_matrix = []
    for i in range(1, n + 1):
        dist_matrix.append(bfs(i))  # O(n^2) with O(n+m) per BFS

    cand_in = [[] for _ in range(n + 1)]
    cand_out = [[] for _ in range(n + 1)]

    # Precompute top 2 candidates for each city
    for j in range(1, n + 1):
        top = sorted([(dist_matrix[i-1][j], i) for i in range(1, n+1) if i != j], reverse=True)
        cand_in[j] = [x[1] for x in top[:2]]

    for k in range(1, n + 1):
        top = sorted([(dist_matrix[k-1][l], l) for l in range(1, n+1) if l != k], reverse=True)
        cand_out[k] = [x[1] for x in top[:2]]

    max_total = -1
    result = []

    for j in range(1, n + 1):
        for k in range(1, n + 1):
            if j == k:
                continue

            best_i, best_l = -1, -1

            for i in cand_in[j]:
                if i != k:
                    best_i = i
                    break

            for l in cand_out[k]:
                if l != j and l != best_i if best_i > 0 else True:
                    best_l = l
                    break

            if best_i > 0 and best_l > 0:
                total = dist_matrix[best_i-1][j-1] + dist_matrix[j-1][k-1] + dist_matrix[k-1][best_l-1]
                if total > max_total:
