def nCr_mod(n, r, p):
    """Compute C(n, r) mod p"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1

    # Compute C(n, r) mod p
    num = 1
    den = 1
    for i in range(r):
        num = (num * (n - i)) % p
        den = (den * (i + 1)) % p

    # Compute modular inverse
    def modinv(a, p):
        return pow(a, p - 2, p)

    return (num * modinv(den, p)) % p

