    def get_and_front(c):
        return c

    def apply_row_belts(row_idx, pos):
        """Simulate going down through a row until we exit or hit an up belt (back to the same state)"""
        visited = set()
        curr, curr_col = row_idx, pos
        while True:
            if (curr, curr_col) in visited:
                return 'loop'
            visited.add((curr, curr_col))

            if curr_col == 0:
                return ('out_left', curr - 1)
            elif curr_col == m + 1:
                return ('out_right', curr)
            elif curr - 1 == 0:
                return ('out_top', m + 1 - m + curr_col - 1)
            elif curr - 1 == n:
                return ('out_bottom', m + 1)
            else:
                belt = grid[curr - 1][curr_col - 1]
                if belt == '^':
                    return ('up_to', curr - 1, curr_col)
                elif belt == '<':
                    if curr_col - 1 == 0:
                        return ('out_left', curr - 1)
                    curr_col -= 1
                else:  # '>'
                    if curr_col - 1 == m:
                        return ('out_right', curr)
                    curr_col += 1

    def simulate(start_x, start_y):
        visited = set()
        curr_x, curr_y = start_x, start_y
