                    return (0, curr_y)
                elif curr_x == n + 1:
                    # Bottom boundary (but according to problem, no way to reach here)
                    return (n + 1, curr_y)
                elif curr_y == 0:
                    return (curr_x, 0)
                elif curr_y == m + 1:
                    return (curr_x, m + 1)

            if (curr_x, curr_y) in visited:
                return (-1, -1)
            visited.add((curr_x, curr_y))

            belt = grid[curr_x - 1][curr_y - 1]
            if belt == '^':
                curr_x -= 1
            elif belt == '<':
                curr_y -= 1
            else:  # '>'
                curr_y += 1

        return (-1, -1)

    output = []
    for i in range(q):
        parts = lines[2 + i].split()
        if parts[0] == 'A':
            x, y = int(parts[1]), int(parts[2])
            result = simulate(x, y)
            output.append(f"{result[0]} {result[1]}")
        else:
            x, y, c = int(parts[1]), int(parts[2]), parts[3]
            grid[x - 1][y - 1] = list(c)[0]

    return '\n'.join(output)
