from collections import deque

class MaxFlow:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.cap = [[0] * n for _ in range(n)]
        self.flow = [[0] * n for _ in range(n)]

    def add_edge(self, u, v, capacity):
        self.graph[u].append([v, len(self.graph[v]), capacity])
        self.graph[v].append([u, len(self.graph[u]) - 1, 0])

    def bfs(self, s, t):
        visited = [False] * self.n
        self.parent = [-1] * self.n
        visited[s] = True

        queue = deque([s])
        while queue:
            u = queue.popleft()
            if u == t:
                break

            for i, (v, rev, cap) in enumerate(self.graph[u]):
                if not visited[v] and cap > 0:
                    visited[v] = True
                    self.parent[v] = u
                    self.mu[v] = i
                    queue.append(v)
                    if v == t:
                        return True
        return not visited[t]

    def dfs(self, u, t, pushed):
        if pushed == 0 or u == t:
            return pushed

        for i, (v, rev, cap) in enumerate(self.graph[u]):
            if self.parent[v] != u or cap == 0:
                continue
            tr = min(pushed, cap)
            tr = self.dfs(v, t, tr)
            if tr == 0:
                continue
            self.graph[u][i][2] -= tr
            self.graph[v][rev][2] += tr
            return tr

        return 0

    def dinic(self, s, t):
        max_flow = 0
        while self.bfs(s, t):
            for i in range(self.n):
                for j in range(len(self.graph[i])):
                    self.graph[i][j][2] = 1
            max_flow += self.dfs(s, t, float('inf'))
        return max_flow

def solve(N, C, surveys):
    m = len(surveys)
    req = [0] * (N + 1)

    for i in range(m):
        s_idx = i + 1
        if i % 2 == 0:
            sz = (i + 1) // 2
            req[sz] = req[sz] + surveys[i]
        else:
            sz = s_idx // 2 + 1
            req[sz] = req[sz] + surveys[i]

    total = sum(req)

    if C >= total:
        return str(total)

    return str(C)

