def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1
        grid = []
        for i in range(n):
            row = list(map(int, lines[idx].split()))
            idx += 1
            grid.append(row)

        # b[i][j] = a[i][j] - i - j
        b = [[grid[i][j] - i - j for j in range(m)] for i in range(n)]

        # dp[i][j] = dict mapping min_s -> min_sum_s
        dp = [[None] * m for _ in range(n)]
        dp[0][0] = {b[0][0]: b[0][0]}

        INF = float('inf')

        for i in range(n):
            for j in range(m):
                if i == 0 and j == 0:
                    continue

                cur = b[i][j]
                new_dict = {}

                sources = []
                if i > 0:
                    sources.append(dp[i-1][j])
                if j > 0:
                    sources.append(dp[i][j-1])

                for source_dict in sources:
                    if source_dict is not None:
                        for pm, ps in source_dict.items():
                            new_pm = min(pm, cur)
                            new_ps = ps + cur
                            if new_pm not in new_dict or new_ps < new_dict[new_pm]:
                                new_dict[new_pm] = new_ps

