import sys

def solution(input_data):
    line = input_data.strip()
    n, k = map(int, line.split())

    MOD = 10**9 + 7

    # Sieve to compute Mobius function mu
    mu = [0] * (k + 1)
    mu[1] = 1
    primes = []
    is_prime = [True] * (k + 1)

    for i in range(2, k + 1):
        if is_prime[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > k:
                break
            is_prime[i * p] = False
            if i % p == 0:
                mu[i * p] = 0
                break
            else:
                mu[i * p] = -mu[i]

    # Precompute powers [i^n mod MOD] for i in [1, k]
    pow_i_n = [0] * (k + 1)
    pow_i_n[0] = 0
    pow_i_n[1] = 1
    for i in range(2, k + 1):
        pow_i_n[i] = pow(i, n, MOD)

    # Compute prefix sums of mu
    mu_prefix = [0] * (k + 1)
    for i in range(1, k + 1):
        mu_prefix[i] = mu_prefix[i-1] + mu[i]

    ans = 0

    # For each i, compute f(i) using sqrt optimization
    for i in range(1, k + 1):
        val_i = 0

        l = 1
        while l <= i:
            r = i // (i // l)
            v = i // l

            mu_sum = mu_prefix[r] - mu_prefix[l-1]

            # Contribution with proper modular arithmetic
            contribution = (mu_sum % MOD + MOD) % MOD * pow_i_n[v]
            val_i = (val_i + contribution) % MOD

            l = r + 1

        ans ^= (val_i + MOD) % MOD

    return f"{ans}\n"
