        for i, t in enumerate(targets):
            if reset_mask == t:
                reset_seen |= (1 << i)

        reset_state = (reset_mask, reset_seen)
        if reset_state not in visited:
            visited.add(reset_state)
            parent[reset_state] = (mask, seen)
            action_taken[reset_state] = "R"
            dist[reset_state] = dist[(mask, seen)] + 1
            queue.append(reset_state)

    result = None
    for state in visited:
        if state[1] == full_seen:
            result = state
            break

    if result is None:
        return "0\n\n"

    path = []
    curr = result
    stop = False
    while curr != start_state:
        path.append(action_taken[curr])
        curr = parent[curr]
        if action_taken[curr] in action_taken:
            stop = True

    path.reverse()
    return f"{len(path)}\n{' '.join(path)}\n"
